import time
from functools import wraps

def cache(ttl_seconds=60):
    cache_store = {}
    def decorator(func):
        @wraps(func)
        def wrapper(*args):
            key = args
            if key in cache_store:
                value, timestamp = cache_store[key]
                if time.time() - timestamp < ttl_seconds:
                    return value
            result = func(*args)
            cache_store[key] = (result, time.time())
            return result
        return wrapper
    return decorator
```

